import React from "react";
import _ from "lodash";

import "../assets/css/loading-page.css";

class LoadingPage extends React.Component {
  constructor(props) {
    super(props);

    this.state = { width: window.outerWidth, height: window.outerHeight };
  }

  componentDidMount() {
    window.addEventListener("resize", () =>
      this.setState({ width: window.outerWidth, height: window.outerHeight })
    );
  }

  render() {
    let radius = 100;
    let bigRadius = 120;

    let width = 40;
    let height = 40;

    let numPoints = 50;

    let x = this.state.width / 2 - width / 3.5;
    let y = this.state.height / 2 - height / 1.5;

    return (
      <div className="loading-page-wrapper">
        <h1
          className="loading-text-wrapper montserrat-light"
          style={{ backgroundColor: "blue" }}
        >
          loading
        </h1>
        {_.times(numPoints, n => {
          const angle = (n * (2 * Math.PI)) / numPoints;

          let offset = 10;

          const firstPointX = (radius + offset) * Math.cos(angle);
          const firstPointY = (radius + offset) * Math.sin(angle);
          const secondPointX = (bigRadius + offset) * Math.cos(angle);
          const secondPointY = (bigRadius + offset) * Math.sin(angle);

          return (
            <div
              className="circle"
              style={{
                offsetPath: `path("M ${x + firstPointX},${
                  y + firstPointY
                } l ${secondPointX},${secondPointY}")`,
                animationDelay: `-${Math.random() * 10}s`
              }}
            ></div>
          );
        })}
        <div
          className="circle"
          style={{
            offsetPath: `path("M ${x},${y}")`,
            animationDelay: `-${Math.random() * 10}s`
          }}
        ></div>
      </div>
    );
  }
}

export default LoadingPage;
